import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:pointycastle/export.dart';
import 'package:swalvo_rtc/src/internal/e2ee_crypto.dart';

/// Checks this SDK's key schedule against the shared vectors
/// (docs/architecture/e2ee-vectors.json, generated by the web SDK), and the
/// frame format with an independent AES-GCM (pointycastle).
///
/// The frame encryption itself is flutter_webrtc's native FrameCryptor
/// (libwebrtc), which cannot run in a unit test. What can be pinned here,
/// and is: the key material this SDK hands that cryptor, the native key
/// schedule it is configured for (HKDF, salt "LivqenoRatchet"), and that
/// the web SDK's frames are exactly libwebrtc's format — so a Flutter
/// receiver configured this way decrypts them. The device-level check is
/// the cross-platform call in docs/rtc/e2ee.mdx's interop checklist.
void main() {
  final vectors = jsonDecode(
    File('../../../docs/architecture/e2ee-vectors.json').readAsStringSync(),
  ) as Map<String, dynamic>;

  Uint8List hex(String value) => Uint8List.fromList([
        for (var i = 0; i < value.length; i += 2)
          int.parse(value.substring(i, i + 2), radix: 16),
      ]);
  String toHex(List<int> bytes) =>
      bytes.map((b) => b.toRadixString(16).padLeft(2, '0')).join();

  group('key schedule', () {
    test('passphrase → material (PBKDF2-SHA256, 100k, "LivqenoE2EE:" + roomId)',
        () {
      final p = vectors['passphrase'] as Map<String, dynamic>;
      final material = deriveMaterialFromPassphrase(
          p['passphrase'] as String, p['roomId'] as String);
      expect(toHex(material), p['material']);
      expect(toHex(aesKeyFromMaterial(material)), p['aesKey']);
    });

    test('ratchet (HKDF-SHA256, salt "LivqenoRatchet", 128 zero bytes of info)',
        () {
      final r = vectors['ratchet'] as Map<String, dynamic>;
      var material = hex(r['from'] as String);
      for (final step in (r['steps'] as List).cast<Map<String, dynamic>>()) {
        material = ratchetMaterial(material);
        expect(toHex(material), step['material']);
        expect(toHex(aesKeyFromMaterial(material)), step['aesKey']);
      }
    });

    test('raw per-participant key → AES key', () {
      final raw = vectors['rawKey'] as Map<String, dynamic>;
      expect(toHex(aesKeyFromMaterial(hex(raw['material'] as String))),
          raw['aesKey']);
    });

    test('PBKDF2 and HKDF against RFC test vectors', () {
      // RFC 7914 §11 PBKDF2-HMAC-SHA256, c = 1.
      expect(
        toHex(pbkdf2Sha256(utf8.encode('passwd'), utf8.encode('salt'), 1, 64)),
        '55ac046e56e3089fec1691c22544b605f94185216dde0465e68b9d57c20dacbc'
        '49ca9cccf179b645991664b39d77ef317c71b845b1e30bd509112041d3a19783',
      );
      // RFC 5869 A.1.
      expect(
        toHex(hkdfSha256(
          hex('0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b'),
          hex('000102030405060708090a0b0c'),
          hex('f0f1f2f3f4f5f6f7f8f9'),
          42,
        )),
        '3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf34007208d5b887185865',
      );
    });
  });

  group('frame format (§3.2)', () {
    Uint8List gcm(bool encrypt, Uint8List key, Uint8List iv, Uint8List aad,
        Uint8List input) {
      final cipher = GCMBlockCipher(AESEngine())
        ..init(encrypt, AEADParameters(KeyParameter(key), 128, iv, aad));
      return cipher.process(input);
    }

    Uint8List unescape(Uint8List data) {
      final out = <int>[];
      for (var i = 0; i < data.length;) {
        if (data.length - i >= 3 &&
            data[i] == 0 &&
            data[i + 1] == 0 &&
            data[i + 2] == 3) {
          out.addAll([0, 0]);
          i += 3;
        } else {
          out.add(data[i++]);
        }
      }
      return Uint8List.fromList(out);
    }

    test(
        'every web vector decrypts with an independent AES-GCM, and re-encrypts identically',
        () {
      final frames = vectors['frames'] as Map<String, dynamic>;
      final key = aesKeyFromMaterial(hex(frames['keyMaterial'] as String));
      for (final frame
          in (frames['cases'] as List).cast<Map<String, dynamic>>()) {
        final data = hex(frame['encrypted'] as String);
        final headerLength = frame['unencryptedBytes'] as int;
        expect(data[data.length - 2], 12,
            reason: '${frame['name']}: IV length byte');
        expect(data[data.length - 1], frame['keyIndex'],
            reason: '${frame['name']}: key index byte');
        final iv = data.sublist(data.length - 14, data.length - 2);
        expect(toHex(iv), frame['iv']);
        final header = data.sublist(0, headerLength);
        var body = data.sublist(headerLength);
        if (frame['codec'] == 'h264') body = unescape(body);
        final payload = body.sublist(0, body.length - 14);
        final plain = gcm(false, key, iv, header, payload);
        expect(toHex([...header, ...plain]), frame['plaintext'],
            reason: frame['name'] as String);

        final reencrypted = gcm(true, key, iv, header, plain);
        expect(toHex(reencrypted), toHex(payload),
            reason: '${frame['name']}: deterministic for a fixed IV');
      }
    });

    test('clear header lengths follow the codec table', () {
      final cases = ((vectors['frames'] as Map)['cases'] as List)
          .cast<Map<String, dynamic>>();
      final byName = {for (final c in cases) c['name']: c['unencryptedBytes']};
      expect(byName['vp8-key'], 10);
      expect(byName['vp8-delta'], 3);
      expect(byName['opus'], 1);
      expect(byName['vp9'], 0);
      expect(byName['h264-idr'], 25);
    });
  });
}
